import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem73 restringe correção Polares e preserva operação',()=>{const p={id:'Evo4CPaNJPvGuj1ILt5u',titulo:'POLARES Z20 Patinete Elétrico Premium 500w Pneu Aderente Velocidade Máxima 32km/h Motorizado Até 30km De Autonomia Polares',preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Capa para '+p.titulo,comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/seguro|premium|qualquer terreno/i);assert.match(x.comentario,/não medições/);});
